        LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setGravity(Gravity.CENTER_HORIZONTAL);card.setPadding(dp(22),dp(30),dp(22),dp(24));card.setBackground(outlined(WHITE,28));LinearLayout.LayoutParams cardLp=lp(-1,-2);cardLp.setMargins(0,dp(52),0,0);root.addView(card,cardLp);
        TextView icon=text("✉",45,Color.WHITE);icon.setGravity(Gravity.CENTER);icon.setBackground(shape(GREEN,22));card.addView(icon,lp(dp(92),dp(92)));
        status=text(tr("အီးမေးလ်ဖန်တီးနေသည်…","Creating email…"),13,GREEN);status.setGravity(Gravity.CENTER);LinearLayout.LayoutParams statLp=lp(-1,-2);statLp.topMargin=dp(22);card.addView(status,statLp);
        email=text(tr("ဖန်တီးနေသည်…","Creating…"),22,INK);email.setTypeface(Typeface.DEFAULT,Typeface.BOLD);email.setGravity(Gravity.CENTER);email.setTextIsSelectable(true);LinearLayout.LayoutParams emailLp=lp(-1,-2);emailLp.setMargins(0,dp(8),0,dp(3));card.addView(email,emailLp);
