        copy=new Button(this);copy.setText(tr("▣  Email ကူးယူမယ်","▣  Copy email"));copy.setTextSize(16);copy.setTextColor(Color.WHITE);copy.setTypeface(Typeface.DEFAULT,Typeface.BOLD);copy.setEnabled(false);copy.setBackground(shape(GREEN,15));LinearLayout.LayoutParams copyLp=lp(-1,dp(58));copyLp.topMargin=dp(34);card.addView(copy,copyLp);

        change=new Button(this);change.setText(tr("↻  Email ပြောင်းမယ်","↻  Change email"));change.setTextSize(16);change.setTextColor(Color.rgb(90,95,104));change.setBackgroundColor(Color.TRANSPARENT);LinearLayout.LayoutParams changeLp=lp(-1,dp(62));changeLp.setMargins(0,dp(18),0,dp(8));root.addView(change,changeLp);

        LinearLayout inboxCard=new LinearLayout(this);inboxCard.setOrientation(LinearLayout.VERTICAL);inboxCard.setPadding(dp(16),dp(15),dp(16),dp(16));inboxCard.setBackground(outlined(WHITE,22));root.addView(inboxCard,lp(-1,-2));
