        inbox=new LinearLayout(this);inbox.setOrientation(LinearLayout.VERTICAL);inboxCard.addView(inbox,lp(-1,-2));showEmpty();

        Button sponsored=new Button(this);sponsored.setText(tr("ကြော်ငြာကြည့်ရန်  ↗","Sponsored offer  ↗"));sponsored.setTextColor(Color.WHITE);sponsored.setTextSize(14);sponsored.setTypeface(Typeface.DEFAULT,Typeface.BOLD);sponsored.setBackground(shape(Color.rgb(35,39,48),12));LinearLayout.LayoutParams adLp=lp(-1,dp(48));adLp.topMargin=dp(18);root.addView(sponsored,adLp);
        TextView nav=text("✉  Email        ▣  Inbox        ★  More",14,INK);nav.setGravity(Gravity.CENTER);nav.setTypeface(Typeface.DEFAULT,Typeface.BOLD);nav.setBackground(shape(WHITE,28));LinearLayout.LayoutParams navLp=lp(-1,dp(62));navLp.topMargin=dp(18);root.addView(nav,navLp);

        copy.setOnClickListener(v->{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Temp email",email.getText()));Toast.makeText(this,tr("ကူးယူပြီးပါပြီ","Email copied"),Toast.LENGTH_SHORT).show();});
